UPDATE agent_run SET status = 'running', lease_version = #{lease}, next_attempt_at = NULL, started_at =
COALESCE(started_at, #{now}), active_segment_started_at = #{now}, updated_at = #{now}
WHERE enterprise_id = #{enterpriseId} AND id = #{id} AND status = 'queued' AND cancel_requested_at IS NULL
